98				return
99			}
100			if len(c.Payload) == 0 {
101				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
102				return
103			}
104			if _, dup := seen[c.ID]; dup {
105				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
106				return
107			}
108			seen[c.ID] = struct{}{}
