13	func changes(ids ...string) []Change {
14		out := make([]Change, len(ids))
15		for i, id := range ids {
16			out[i] = Change{ID: id, DeviceID: "dev-1", Payload: json.RawMessage(fmt.Sprintf(`{"n":%d}`, i+1))}
17		}
18		return out
19	}
