21	func TestPostAndListBasic(t *testing.T) {
22		s, err := Open("")
23		if err != nil {
24			t.Fatal(err)
25		}
26		defer func() { _ = s.Close() }()
27	
28		results, err := s.PostChanges("doc-a", changes("c1", "c2", "c3"))
29		if err != nil {
30			t.Fatal(err)
31		}
32		if len(results) != 3 {
33			t.Fatalf("got %d results, want 3", len(results))
34		}
35		for i, r := range results {
36			if !r.Created || r.Cursor != int64(i+1) {
37				t.Fatalf("result %d = %+v, want created cursor %d", i, r, i+1)
38			}
39			if r.ID != []string{"c1", "c2", "c3"}[i] {
40				t.Fatalf("result %d id = %q, wrong order", i, r.ID)
41			}
42		}
43	
44		got, next, err := s.ListChanges("doc-a", 0, 100)
45		if err != nil {
46			t.Fatal(err)
47		}
