59	func TestIdempotentRepost(t *testing.T) {
60		s, _ := Open("")
61		defer func() { _ = s.Close() }()
62	
63		first, err := s.PostChanges("doc", []Change{
64			{ID: "x1", DeviceID: "dev", Payload: json.RawMessage(`{"a":1,"b":2}`)},
65		})
66		if err != nil {
67			t.Fatal(err)
68		}
69	
70		// Same deviceId and semantically equal payload (reordered keys, whitespace):
71		// idempotent, cursor stays the first value.
72		again, err := s.PostChanges("doc", []Change{
73			{ID: "x1", DeviceID: "dev", Payload: json.RawMessage(`{ "b": 2, "a": 1 }`)},
74		})
75		if err != nil {
76			t.Fatalf("idempotent repost: %v", err)
77		}
78		if again[0].Created || again[0].Cursor != first[0].Cursor || again[0].Cursor != 1 {
79			t.Fatalf("repost result = %+v, want created=false cursor=1", again[0])
80		}
81	
82		// Number vs number-with-fraction decode identically.
83		again2, err := s.PostChanges("doc", []Change{
84			{ID: "x1", DeviceID: "dev", Payload: json.RawMessage(`{"a":1.0,"b":2}`)},
85		})
86		if err != nil {
87			t.Fatalf("numeric-equivalent repost: %v", err)
88		}
89		if again2[0].Created {
90			t.Fatalf("expected idempotent for 1 vs 1.0")
91		}
92	}
93	
94	func TestConflictZeroWrite(t *testing.T) {
95		s, _ := Open("")
96		defer func() { _ = s.Close() }()
97	
98		if _, err := s.PostChanges("doc", []Change{
99			{ID: "x1", DeviceID: "dev", Payload: json.RawMessage(`{"v":1}`)},
100		}); err != nil {
101			t.Fatal(err)
102		}
103	
104		// Different payload -> 409-equivalent conflict, and the new id in the same
105		// batch must not be written.
106		_, err := s.PostChanges("doc", []Change{
107			{ID: "new-1", DeviceID: "dev", Payload: json.RawMessage(`{"v":2}`)},
108			{ID: "x1", DeviceID: "dev", Payload: json.RawMessage(`{"v":99}`)},
109		})
110		var conflict *ErrConflict
111		if !errors.As(err, &conflict) || conflict.ID != "x1" {
112			t.Fatalf("want *ErrConflict{x1}, got %v", err)
113		}
114		rows, _, err := s.ListChanges("doc", 0, 100)
115		if err != nil {
116			t.Fatal(err)
117		}
118		if len(rows) != 1 || rows[0].ID != "x1" {
119			t.Fatalf("batch was not zero-write: %+v", rows)
120		}
121	
122		// Different deviceId -> conflict as well.
123		_, err = s.PostChanges("doc", []Change{
124			{ID: "x1", DeviceID: "other", Payload: json.RawMessage(`{"v":1}`)},
125		})
126		if !errors.As(err, &conflict) {
127			t.Fatalf("device mismatch want conflict, got %v", err)
128		}
129	}
130	
131	func TestListPaginationAndUnknownDocument(t *testing.T) {
132		s, _ := Open("")
133		defer func() { _ = s.Close() }()
134	
135		if _, err := s.PostChanges("doc", changes("a", "b", "c", "d", "e")); err != nil {
136			t.Fatal(err)
137		}
138	
139		page, next, err := s.ListChanges("doc", 0, 2)
140		if err != nil {
141			t.Fatal(err)
142		}
143		if len(page) != 2 || page[0].ID != "a" || page[1].ID != "b" || next != 2 {
144			t.Fatalf("page1 = %+v next=%d", page, next)
145		}
146	
147		page, next, err = s.ListChanges("doc", next, 2)
148		if err != nil {
149			t.Fatal(err)
150		}
151		if len(page) != 2 || page[0].ID != "c" || next != 4 {
152			t.Fatalf("page2 = %+v next=%d", page, next)
153		}
154	
155		// Known document, nothing past the last cursor -> empty page, nextCursor == after.
156		page, next, err = s.ListChanges("doc", 5, 100)
157		if err != nil {
158			t.Fatal(err)
159		}
160		if len(page) != 0 || next != 5 {
161			t.Fatalf("tail = %+v next=%d, want empty next=5", page, next)
162		}
163	
