	// survives restart too.
	res, err := s2.MergeChange("doc", "dev", 2, mergeChange("c3", "dev", `{"c":3}`))
	if err != nil || res.Outcome != MergeApplied || res.Cursor != 3 {
		t.Fatalf("post-restart apply = %+v err=%v", res, err)
