65	func (g *documentGuard) ServeHTTP(w http.ResponseWriter, r *http.Request) {
66		if p := r.URL.Path; strings.HasPrefix(p, "/v1/documents/") {
67			rest := p[len("/v1/documents/"):]
68			segment := rest
