104			return
105		}
106		// Reject trailing data after the JSON object.
107		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
108			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
109			return
110		}
111	
112		if req.DeviceID == "" {
