126				return
127			}
128			if len(c.Payload) == 0 {
129				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
130				return
131			}
132			if _, dup := seen[c.ID]; dup {
133				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
134				return
